package shortcuts
import v2 "example.test/app/services/tables"
func SaveShortcuts(req *SaveShortcutsRequest) QueryShortcutsResponse {
 persist(req.Shortcuts)
 return QueryShortcuts()
}
func persist(rows []ShortcutItem) {
 v2.Exec("shortcuts.upsert db=mysql", rows)
}
func QueryShortcuts() QueryShortcutsResponse {
 return v2.Select[QueryShortcutsResponse]("shortcuts.query_by_open_id db=mysql")
}
func UnrelatedExport() { panic("not this request") }

